/// <summary>
/// AVA/WEN/2025/02/03   AVA_012548_WrkCtrTable_WrkCtrGroupFields
/// </summary>
/// <param name = "sender">FormDataSource</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(WrkCtrResourceGroup, WrkCtrTable), FormDataSourceEventType::Initialized)]
public static void WrkCtrTable_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)
{
    sender.object(fieldNum(WrkCtrTable, QueueTimeAfter)).enabled(true);
    sender.object(fieldNum(WrkCtrTable, QueueTimeBefore)).enabled(true);
    sender.object(fieldNum(WrkCtrTable, ToHours)).enabled(true);
    sender.object(FieldNum(WrkCtrTable, TranspTime)).enabled(true);
    sender.object(fieldNum(WrkCtrTable, SetupTime)).enabled(true);
    sender.object(fieldNum(WrkCtrTable, ProcessTime)).enabled(true);
    sender.object(fieldNum(WrkCtrTable, ProcessPerQty)).enabled(true);
}
